	$('.site').click(function(){
		if ($(this).hasClass('on')) {
			$(this).removeClass('on');
		} else {
			$(this).addClass('on');
		}
	});
	$('.site').mouseleave(function(){
		$(this).removeClass('on');
	});
	/* SCROLL */
	$('.scroll').hover(function(){
		$(this).addClass('on');
	});
	$('.scroll').scroll(function(){
		$(this).addClass('on');
	});
